// once the cwd is found. project carries the result out of the callback.
type stopReader struct {
	r       io.Reader
	stopped bool
	project string
}

func (s *stopReader) Read(p []byte) (int, error) {
	if s.stopped {
		return 0, io.EOF
	}
	return s.r.Read(p)
