1	package agentusage
2	
3	import (
4		"io"
5		"path/filepath"
6		"sort"
7	)
8	
9	// ParseSession aggregates the usage of every agent of a session. It fails
10	// only if the parent transcript cannot be opened; a sub-agent that cannot be
11	// read stays in Agents with no tokens and a FileIssue.
12	func ParseSession(files SessionFiles) (Usage, error) {
13		subs := append([]SubAgentFiles(nil), files.SubAgents...)
14		sort.Slice(subs, func(i, j int) bool { return subs[i].ID < subs[j].ID })
15		agg := newAggregator([]Agent{{Main: true, State: StateUnknown}})
16		if err := parseFile(agg, 0, files.Parent); err != nil {
17			return Usage{}, baseOnly(err)
18		}
19		for _, sa := range subs {
20			agg.agents = append(agg.agents, agentFromMeta(&agg.diag, sa))
21			if err := parseFile(agg, len(agg.agents)-1, sa.Transcript); err != nil {
22				agg.addIssue(FileIssue{File: sanitizeLabel(filepath.Base(sa.Transcript)), Kind: IssueOpenFailed})
23			}
24		}
25		return Usage{
26			SessionID:   sanitizeLabel(files.ID),
27			Agents:      agg.finish(),
28			Versions:    agg.versions(),
29			Diagnostics: agg.diag,
30		}, nil
31	}
32	
33	// agentFromMeta builds a sub-agent's identity from its meta file, counting
34	// a missing or unreadable one in diag.
35	func agentFromMeta(diag *Diagnostics, sa SubAgentFiles) Agent {
36		ag := Agent{ID: sanitizeLabel(sa.ID)}
37		if sa.Meta == "" {
38			diag.MetaMissing++
39			return ag
40		}
41		m, err := readMeta(sa.Meta)
42		if err != nil {
43			diag.MetaUnreadable++
44			return ag
45		}
46		ag.Type, ag.State, ag.SpawnDepth = m.AgentType, m.state(), m.SpawnDepth
47		return ag
48	}
49	
50	// parseFile folds one transcript into the aggregator for agent idx. It
51	// fails only if the file cannot be opened.
52	func parseFile(agg *aggregator, idx int, path string) error {
53		f, err := openPlain(path, false)
54		if err != nil {
55			return err
56		}
57		if f == nil {
58			return errNotRegular
59		}
60		defer func() { _ = f.Close() }()
61		parseReader(agg, idx, sanitizeLabel(filepath.Base(path)), f)
62		return nil
63	}
64	
65	// parseReader folds r into agg for agent idx; name is the file's sanitized
66	// base name. A read error mid-stream keeps what was read and is recorded as
67	// an IssueReadError at the offset consumed; it is not an unreadable line.
68	func parseReader(agg *aggregator, idx int, name string, r io.Reader) {
69		start := len(agg.diag.Files)
70		res, err := scanLines(r, MaxLineBytes, func(line []byte, off int64) {
71			agg.addLine(idx, name, off, line)
72		})
73		for _, off := range res.OversizedAt {
74			agg.diag.OversizedLines++
75			agg.addIssue(FileIssue{File: name, Offset: off, Kind: IssueOversized})
76		}
77		if err != nil {
78			agg.addIssue(FileIssue{File: name, Offset: res.Consumed, Kind: IssueReadError})
79		}
80		if len(res.Tail) > 0 {
81			agg.diag.TruncatedFiles = append(agg.diag.TruncatedFiles, name)
82		}
83		issues := agg.diag.Files[start:]
84		sort.SliceStable(issues, func(i, j int) bool { return issues[i].Offset < issues[j].Offset })
85	}
