43	// ListSessions lists <root>/<project>/<uuid>.jsonl, one level deep and never
44	// recursively. A missing root is an empty Listing and no error; a root that is
45	// not a directory or cannot be read is an error naming the base name only.
46	// The root itself may be a symbolic link (the user may link ~/.claude/projects
47	// elsewhere, and it is their own choice); anything below it may not.
48	func ListSessions(root string) (Listing, error) {
49		info, err := os.Stat(root)
50		if os.IsNotExist(err) {
51			return Listing{}, nil
52		}
53		if err != nil {
54			return Listing{}, baseOnly(err)
55		}
56		if !info.IsDir() {
57			return Listing{}, fmt.Errorf("agentusage: %s is not a directory", filepath.Base(root))
58		}
59		projects, err := os.ReadDir(root)
60		if err != nil {
61			return Listing{}, baseOnly(err)
62		}
63		var (
64			list  Listing
65			found []Session
66		)
67		for _, p := range projects {
68			switch {
69			case p.Type()&os.ModeSymlink != 0:
70				list.Omitted++
71			case p.IsDir():
72				sessions, omitted := projectSessions(filepath.Join(root, p.Name()))
73				found = append(found, sessions...)
74				list.Omitted += omitted
75			}
76		}
77		sort.Slice(found, func(i, j int) bool {
78			if !found[i].ModTime.Equal(found[j].ModTime) {
79				return found[i].ModTime.After(found[j].ModTime)
80			}
81			return found[i].ID < found[j].ID
82		})
83		if len(found) > maxSessions {
84			list.Omitted += len(found) - maxSessions
85			found = found[:maxSessions]
86		}
87		for i := range found {
88			found[i].Project = readProject(found[i].Parent)
89		}
90		list.Sessions = found
91		return list, nil
92	}
93	
94	// projectSessions returns the sessions directly inside dir, without their
95	// Project, and how many entries were refused. An unreadable dir counts as one.
96	func projectSessions(dir string) ([]Session, int) {
97		f, _ := openPlain(dir, true)
98		if f == nil {
99			return nil, 1 // unreadable, or a link swapped in since the root was listed
100		}
101		defer func() { _ = f.Close() }()
102		entries, err := f.ReadDir(-1)
103		if err != nil {
104			return nil, 1
105		}
106		var (
107			out     []Session
108			omitted int
109		)
110		for _, e := range entries {
111			name := e.Name()
112			id := strings.TrimSuffix(name, transcriptExt)
113			if id == "" || id == name || strings.HasPrefix(name, agentPrefix) || e.IsDir() {
114				continue // not a session: other file, old sub-agent layout, session directory
115			}
116			info, err := e.Info()
117			if err != nil || !e.Type().IsRegular() {
118				omitted++
119				continue
120			}
121			out = append(out, Session{ID: sanitizeLabel(id), Parent: filepath.Join(dir, name), ModTime: info.ModTime()})
122		}
123		return out, omitted
124	}
125	
126	// readProject returns the first non-empty string cwd found in the first
127	// cwdProbeBytes of the transcript at path, sanitized. Any failure, or no cwd,
128	// yields "". Nothing else of the transcript is kept.
129	func readProject(path string) string {
130		f, _ := openPlain(path, false)
131		if f == nil {
132			return ""
133		}
134		defer func() { _ = f.Close() }()
135		r := &stopReader{r: io.LimitReader(f, cwdProbeBytes)}
136		_, _ = scanLines(r, MaxLineBytes, func(line []byte, _ int64) {
137			if r.stopped {
138				return
139			}
140			var rec struct {
141				Cwd json.RawMessage `json:"cwd"`
142			}
143			if json.Unmarshal(line, &rec) != nil {
144				return
145			}
146			if cwd := optString(rec.Cwd); cwd != "" {
147				r.project, r.stopped = sanitize(cwd, maxPathLen), true
148			}
149		})
150		return r.project
151	}
152	
153	// stopReader reads r until stopped is set, then reports io.EOF, so a scan ends
154	// once the cwd is found. project carries the result out of the callback.
155	type stopReader struct {
156		r       io.Reader
157		stopped bool
158		project string
159	}
160	
161	func (s *stopReader) Read(p []byte) (int, error) {
162		if s.stopped {
163			return 0, io.EOF
164		}
165		return s.r.Read(p)
166	}
